{"implementation": "def solve(case):
    import json
    try:
        payload = case['payload']
        threshold = payload['threshold']
        calls = payload['calls']
    except (KeyError, TypeError):
        raise ValueError('Invalid case structure')
    if not isinstance(threshold, (int, float)):
        raise ValueError('threshold must be numeric')
    if not isinstance(calls, list):
        raise ValueError('calls must be a list')
    accepted = []
    diagnostics = []
    for call in calls:
        try:
            call_id = call['call_id']
            loss_without = call['loss_without_call']
            loss_with = call['loss_with_call']
            pred_tokens = call['prediction_tokens']
            parseable = call['parseable']
        except (KeyError, TypeError):
            raise ValueError('Call missing required field')
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError('prediction_tokens must be positive integer')
        if not isinstance(parseable, bool):
            raise ValueError('parseable must be boolean')
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        diag = {
            'call_id': call_id,
            'gain': round(gain, 8),
            'normalized_gain': round(normalized_gain, 8),
            'parseable': parseable,
            'passed': parseable and normalized_gain >= threshold
        }
        diagnostics.append(diag)
        if diag['passed']:
            accepted.append(call_id)
    total_gain = sum(d['gain'] for d in diagnostics if d['passed'])
    total_normalized = sum(d['normalized_gain'] for d in diagnostics if d['passed'])
    aggregate = {
        'accepted_count': len(accepted),
        'total_gain': round(total_gain, 8),
        'total_normalized_gain': round(total_normalized, 8)
    }
    return {'accepted': accepted, 'diagnostics': diagnostics, 'aggregate': aggregate}"}
